Gov. Janet Mills, who suspended her flagging Democratic U.S. Senate primary last week, has not yet filed paperwork to formally drop out.

Because her move came less than the required 70-day threshold before the June 9 primary, Mills’ name cannot be removed from the ballot against frontrunner Graham Platner and 2024 U.S. Senate nominee David Costello. Votes cast for the outgoing governor will count unless she files a notice to withdraw with the state. If she does, votes for her would count as blank.

The lack of a withdrawal notice almost a week after Mills’ announcement adds a new wrinkle to what was a contentious primary. Democrats hope to rally around the energy and enthusiasm built by the progressive newcomer Platner as he’s barnstormed the state since last summer. The party is also banking on anger at President Donald Trump and Republicans in Congress.

Mills’ suspension followed a struggle to raise money to combat Platner’s momentum and keep a campaign hoping to oust longtime U.S. Sen. Susan Collins afloat. The move shook up one of the most pivotal Senate races in the country, marking a turning point after Mills was recruited by Senate Minority Leader Chuck Schumer and backed by many established Democratic lawmakers and liberal groups.

It’s unclear whether Mills is delaying her notice as part of a strategy. Campaign spokesperson Tommy Garcia did not respond to a request for comment. But her campaign had not filed one as of Tuesday afternoon, Jana Spalding, a spokesperson for Secretary of State Shenna Bellows, said.

Once state officials receive the notice of intent to withdraw, the secretary of state’s office issues a notice informing voters that the candidate has withdrawn and that a vote for that candidate will not be counted, according to state election procedure.

The notice from the state must also be sent along with all absentee ballots requested after local officials receive it. The notice also must be posted on the secretary of state’s website and outside the guardrail enclosure in each voting booth on Election Day.

(function () {
  'use strict';

  /* ---------- Config ---------------------------------------------------- */
  var PAYWALL_SPLIT = 0.50;          // probability of the paywall variant
  var CID           = '14760';

  var FK_PAYWALL    = 'ecsf1je1';
  var FK_ORIGINAL   = 'pg5v5u02';
  var FK_NATION     = 'YMiUyDWe';
  var FK_SPORTS     = 'AX3UKQ10';

  var ANCHOR_PAYWALL  = '#bdn-paywall';
  var ANCHOR_ORIGINAL = '#bdn_paywall_content';

  var ANCHOR_FALLBACK = null;        // e.g. '.entry-content'
  var FLOAT_ON_FALLBACK = false;     // don't float from an unverified anchor

  /* ---------- Single-run guard ------------------------------------------ */
  if (window.__bdnStnBooted) {
    console.warn('[STN] bootstrap already ran on this page — skipping');
    return;
  }
  window.__bdnStnBooted = true;

  /* ---------- Debug / override plumbing --------------------------------- */
  var params = new URLSearchParams(window.location.search);
  var force  = params.get('stnfk');
  var DEBUG  = params.get('stndebug') === '1' || !!force;

  function log() {
    if (!DEBUG) return;
    console.log.apply(console, ['[STN]'].concat([].slice.call(arguments)));
  }
  function warn() {
    console.warn.apply(console, ['[STN]'].concat([].slice.call(arguments)));
  }

  var KEYWORDS = { paywall: 1, original: 1, off: 1 };

  /* ---------- DataLayer helper ------------------------------------------ */
  window.dataLayer = window.dataLayer || [];
  var _pushedOnce = false;

  window.sendPlayerIdToDataLayer = function (id, phase) {
    if (!id) return;
    phase = phase || 'init';
    if (phase === 'init' && _pushedOnce) return;
    if (phase === 'init') _pushedOnce = true;

    window.dataLayer.push({
      event: 'videoPlayerID',
      playerID: id,
      phase: phase
    });
    log('dataLayer push', { playerID: id, phase: phase });
  };

  /* ---------- DOM helpers ----------------------------------------------- */
  function ready(fn) {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', fn, { once: true });
    } else {
      fn();
    }
  }

  // Checks immediately, then polls. Original version lost the first interval.
  function waitFor(selector, intervalMs, timeoutMs, onFound, onTimeout) {
    var immediate = document.querySelector(selector);
    if (immediate) { onFound(immediate); return; }

    var waited = 0;
    var id = setInterval(function () {
      var el = document.querySelector(selector);
      if (el) {
        clearInterval(id);
        onFound(el);
      } else if ((waited += intervalMs) >= timeoutMs) {
        clearInterval(id);
        onTimeout && onTimeout();
      }
    }, intervalMs);
  }

  function makePlayerDiv(fk, allowFloat) {
    var divElm = document.createElement('div');
    divElm.classList.add('s2nPlayer', 'k-' + fk);
    if (allowFloat) divElm.setAttribute('data-type', 'float');
    divElm.setAttribute('data-s2n-api', 'setupS2NApi');
    return divElm;
  }

  function injectScript(fk) {
    var scriptElm = document.createElement('script');
    scriptElm.type = 'text/javascript';
    scriptElm.setAttribute('data-type', 's2nScript');
    scriptElm.src = '//embed.sendtonews.com/player3/embedcode.js?fk=' + fk +
      '&cid=' + CID +
      '&offsetx=0&offsety=0&floatwidth=400&floatposition=bottom-right';
    document.body.appendChild(scriptElm);
    log('embed script injected for fk', fk);
  }

  /* ---------- Main ------------------------------------------------------ */
  ready(function start() {

    if (force === 'off') {
      log('suppressed via ?stnfk=off');
      return;
    }

    /* --- Path parsing --- */
    var pathArray = window.location.pathname.split('/');
    var parentLevelLocation = pathArray[4];
    var childLevelLocation  = pathArray[5];
    log('path segments', pathArray, {
      parent: parentLevelLocation,
      child: childLevelLocation
    });

    /* --- Kill switch (now evaluated after DOM ready, not at parse time) --- */
    var primaryEl = document.getElementById('primary');
    if (!primaryEl) {
      warn('#primary not found — tag-video / tag-nostn kill switch cannot be evaluated');
    }
    var videoCheck = primaryEl ? (primaryEl.getAttribute('class') || '') : '';

    if (videoCheck.indexOf('tag-video') !== -1 || videoCheck.indexOf('tag-nostn') !== -1) {
      log('kill switch active (' + videoCheck + ') — no player');
      return;
    }

    /* --- Variant selection --- */
    var usePaywallVariant;
    if (force === 'paywall')       usePaywallVariant = true;
    else if (force === 'original') usePaywallVariant = false;
    else                           usePaywallVariant = Math.random() < PAYWALL_SPLIT;

    var baseFk = usePaywallVariant ? FK_PAYWALL : FK_ORIGINAL;

    var STNfk;
    var placementMode = 'original';   // 'original' | 'paywall'

    if (childLevelLocation === 'nation' || parentLevelLocation === 'national-politics') {
      STNfk = FK_NATION;
      placementMode = 'original';
    } else if (
      parentLevelLocation === 'sports' ||
      parentLevelLocation === 'high-school-sports' ||
      parentLevelLocation === 'professional-sports' ||
      parentLevelLocation === 'college-sports'
    ) {
      STNfk = FK_SPORTS;
      placementMode = 'original';
    } else {
      STNfk = baseFk;
      placementMode = usePaywallVariant ? 'paywall' : 'original';
    }

    // Raw feed-key override — bypasses the section rules entirely.
    if (force && !KEYWORDS[force]) {
      STNfk = force;
      placementMode = params.get('stnmode') === 'paywall' ? 'paywall' : 'original';
      log('raw fk override', STNfk, 'mode', placementMode);
    } else if (force === 'paywall' || force === 'original') {
      // Keep placement in step with a forced variant even in a section-ruled URL.
      placementMode = force;
      STNfk = baseFk;
    }

    if (!STNfk) { log('no fk resolved — suppressed'); return; }

    log('resolved', { fk: STNfk, placementMode: placementMode, forced: force || false });
    window.STNfk = STNfk;
    window.sendPlayerIdToDataLayer(STNfk, 'init');

    /* --- Anchor resolution: ordered chain, no body fallback --- */
    var chain = (placementMode === 'paywall')
      ? [[ANCHOR_PAYWALL, 250, 3000], [ANCHOR_ORIGINAL, 200, 1000]]
      : [[ANCHOR_ORIGINAL, 200, 1000]];

    if (ANCHOR_FALLBACK) chain.push([ANCHOR_FALLBACK, 200, 500]);

    (function tryNext(i) {
      if (i >= chain.length) {
        warn('no valid anchor found in ' + placementMode +
             ' mode — suppressing player rather than appending to <body>');
        return;
      }
      var step = chain[i];
      waitFor(step[0], step[1], step[2],
        function (el) { place(el, step[0], i); },
        function () {
          log('anchor miss: ' + step[0] + ' (waited ' + step[2] + 'ms)');
          tryNext(i + 1);
        }
      );
    })(0);

    function place(anchorEl, selector, chainIndex) {
      var isFallback = ANCHOR_FALLBACK && selector === ANCHOR_FALLBACK;
      var allowFloat = isFallback ? FLOAT_ON_FALLBACK : true;

      var playerDiv = makePlayerDiv(STNfk, allowFloat);
      anchorEl.insertAdjacentElement('afterend', playerDiv);

      log('placed after ' + selector, {
        step: chainIndex,
        float: allowFloat,
        parent: playerDiv.parentNode && playerDiv.parentNode.tagName
      });

      injectScript(STNfk);

      // Width sanity check — a player as wide as the viewport is the takeover.
      if (DEBUG) {
        setTimeout(function () {
          var el = document.querySelector('.k-' + STNfk);
          if (!el) { warn('player div vanished after injection'); return; }
          var w = Math.round(el.getBoundingClientRect().width);
          log('player width ' + w + 'px vs viewport ' + window.innerWidth + 'px', {
            parent: el.parentNode.tagName + (el.parentNode.id ? '#' + el.parentNode.id : '')
          });
          if (el.parentNode === document.body) warn('player is a direct child of <body>');
          if (w >= window.innerWidth - 2) warn('player is full viewport width');
        }, 2500);
      }
    }
  });

  /* ---------- STN API hookup + float behavior --------------------------- */
  window.setupS2NApi = function (getS2NApiForPlayer) {
    var s2nPlayer = document.querySelector('.k-' + window.STNfk);
    if (!s2nPlayer) {
      console.error('setupS2NApi: Embed code <div> not found.');
      return;
    }

    var s2nApi = getS2NApiForPlayer(s2nPlayer);
    window._s2nAPI = s2nApi;
    if (!s2nApi) {
      console.error('setupS2NApi: API request has been denied. See your STN contact for more details.');
      return;
    }

    window.sendPlayerIdToDataLayer(window.STNfk, 'ready');

    function getCookie(cname) {
      var name = cname + '=', ca = document.cookie.split(';');
      for (var i = 0; i < ca.length; i++) {
        var c = ca[i];
        while (c.charAt(0) === ' ') c = c.substring(1);
        if (c.indexOf(name) === 0) return c.substring(name.length, c.length);
      }
      return '';
    }

    // Re-derive rather than relying on closure state from the boot IIFE.
    var section = window.location.pathname.split('/')[4];
    var isUserSubscribed = getCookie('bdn_subscriber');

    if (isUserSubscribed !== '' || section === 'mainefocus') {
      s2nApi.float = false;
    } else {
      s2nApi.float = true;
    }
    console.log('[STN] float =', s2nApi.float);
  };
})();





